input.command:
PLUGIN_ROOT=$PWD/plugins/dev-graph; python3 "$PLUGIN_ROOT/scripts/build-graph-node.py" link-github --repo-root "$PWD" --input .dev-graph/cache/sync-run1/link-input-1.json > $TMPDIR/apply.json; echo "rc=$?"; python3 -c "
import json,sys;d=json.load(open(sys.argv[1]))
for k in ['status','valid','applied_count','write_count','graph_revision_before','graph_revision_after','graph_digest_after','receipt_path','pre_write_validation','findings','node_ids']: print(k,'=',d.get(k))
" $TMPDIR/apply.json; ls .dev-graph/state/receipts/ | tail -3; python3 -c "import json;g=json.load(open('.dev-graph/state/graph.json'));print('graph rev',g.get('graph_revision'),g.get('graph_digest'))"

